import type { RouterToolDefinition } from "@agent-in-box/protocol";

/**
 * Pi loads this file with `--extension`. It exposes only the Router tool broker
 * and no shell, filesystem, Supervisor or VM input capability.
 */
export function routerExtensionSource(tools: RouterToolDefinition[]): string {
  return `import { Type } from "typebox";

// Generated by Agent-in-Box. Do not edit the copy under the data directory.
const TOOLS = ${JSON.stringify(tools, null, 2)};

function routerUrl() {
  const value = (process.env.AGENT_IN_BOX_ROUTER_URL || "").trim();
  if (!value) throw new Error("AGENT_IN_BOX_ROUTER_URL is not configured for the Router session");
  return value.replace(/\\/$/, "");
}

function routerToken() {
  const value = (process.env.AGENT_IN_BOX_ROUTER_TOKEN || "").trim();
  if (!value) throw new Error("AGENT_IN_BOX_ROUTER_TOKEN is not configured for the Router session");
  return value;
}

function schema(parameters) {
  return Type.Unsafe ? Type.Unsafe(parameters) : parameters;
}

export default function registerRouterTools(pi) {
  for (const tool of TOOLS) {
    pi.registerTool({
      name: tool.name,
      label: tool.name,
      description: tool.description,
      parameters: schema(tool.parameters),
      async execute(_id, params, signal) {
        const response = await fetch(
          routerUrl() + "/v1/tools/" + encodeURIComponent(tool.name),
          {
            method: "POST",
            headers: {
              accept: "application/json",
              authorization: "Bearer " + routerToken(),
              "content-type": "application/json; charset=utf-8",
            },
            body: JSON.stringify(params ?? {}),
            signal,
          },
        );
        let payload;
        try {
          payload = await response.json();
        } catch {
          throw new Error("Router tool broker returned HTTP " + response.status + " without JSON");
        }
        if (!response.ok || payload?.ok !== true) {
          const message = payload?.error?.message || "Router tool broker HTTP " + response.status;
          const code = payload?.error?.code ? " [" + payload.error.code + "]" : "";
          throw new Error(message + code);
        }
        return {
          content: [{ type: "text", text: JSON.stringify(payload.result) }],
          details: payload.result,
        };
      },
    });
  }
}
`;
}
